// Проверка подписи Prodamus (HMAC-SHA256). Секрет ТОЛЬКО из $env.PRODAMUS_SECRET (не хардкод).
// ВНИМАНИЕ: точная сериализация Prodamus (их Hmac SDK) НЕ раскрыта в доках — ОБЯЗАТЕЛЬНО сверить calc==Sign
// на реальном тест-уведомлении и при необходимости поправить buildQuery/phpStr под их схему.
const crypto = require('crypto');
const SECRET = $env.PRODAMUS_SECRET || '';
const body = $('Shop').item.json.body || {};
const headers = $('Shop').item.json.headers || {};
const sign = String(headers['sign'] || headers['Sign'] || '').toLowerCase();
function phpStr(v){ if (v === true) return '1'; if (v === false || v === null || v === undefined) return ''; return String(v); }
function ksortDeep(o){ if (Array.isArray(o)) return o.map(ksortDeep); if (o && typeof o === 'object'){ const out={}; for (const k of Object.keys(o).sort()) out[k]=ksortDeep(o[k]); return out; } return o; }
function buildQuery(data, prefix){ const parts=[]; const enc=s=>encodeURIComponent(String(s)).replace(/%20/g,'+'); for (const k of Object.keys(data)){ const key=prefix?prefix+'['+k+']':k; const val=data[k]; if (val!==null && typeof val==='object'){ const sub=buildQuery(val,key); if (sub) parts.push(sub); } else { parts.push(enc(key)+'='+enc(phpStr(val))); } } return parts.join('&'); }
const serialized = buildQuery(ksortDeep(body), '');
const calc = SECRET ? crypto.createHmac('sha256', SECRET).update(serialized).digest('hex') : '';
return [{ json: { sig_ok: !!calc && calc === sign, sign_present: !!sign, order_num: body.order_num, sum: body.sum } }];
